def levels(g, start):
    seen = {start}
    q = deque([start])
    res = []
    while q:
        res.append(list(q))
        for _ in range(len(q)):
            u = q.popleft()
            for v in g[u]:
                if v not in seen:
                    seen.add(v)
                    q.append(v)
    return res

def count_components(g):
    visited = [False] * len(g)
    count = 0
    for u in range(len(g)):
        if not visited[u]:
            count += 1
            stack = [u]
            visited[u] = True
            while stack:
                v = stack.pop()
                for w in g[v]:
                    if not visited[w]:
                        visited[w] = True
                        stack.append(w)
    return count

def components_from_dsu(n, edges):
    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    for u, v in edges:
        pu, pv = find(u), find(v)
        if pu != pv:
            parent[pu] = pv
    return len({find(i) for i in range(n)})

