def is_bipartite(g):
    color = [-1] * len(g)
    for s in range(len(g)):
        if color[s] != -1:
            continue
        color[s] = 0
        q = deque([s])
        while q:
            u = q.popleft()
            for v in g[u]:
                if color[v] == -1:
                    color[v] = color[u] ^ 1
                    q.append(v)
                elif color[v] == color[u]:
                    return False
    return True

def dfs_color(g, u, c, color):
    color[u] = c
    for v in g[u]:
        if color[v] == -1:
            if not dfs_color(g, v, c ^ 1, color):
                return False
        elif color[v] == c:
            return False
    return True

def is_bipartite(g):
    color = [-1] * len(g)
    return all(
        color[u] != -1 or dfs_color(g, u, 0, color)
        for u in range(len(g))
    )

def topo_sort(g):
    visited = [False] * len(g)
    order = []
    def dfs(u):
        visited[u] = True
        for v in g[u]:
            if not visited[v]:
                dfs(v)
        order.append(u)
    for u in range(len(g)):
        if not visited[u]:
            dfs(u)
    return order[::-1]

def topo_sort_detect(g):
    WHITE, GRAY, BLACK = 0, 1, 2
    state = [WHITE] * len(g)
    order = []
    def dfs(u):
        state[u] = GRAY
        for v in g[u]:
            if state[v] == GRAY:
                return False
            if state[v] == WHITE and not dfs(v):
                return False
        state[u] = BLACK
        order.append(u)
        return True
    for u in range(len(g)):
        if state[u] == WHITE and not dfs(u):
            return None
    return order[::-1]

