def prim_mst(g, start=0):
    n = len(g)
    in_tree = [False] * n
    total = 0
    pq = [(0, start)]
    while pq:
        w, u = heapq.heappop(pq)
        if in_tree[u]:
            continue
        in_tree[u] = True
        total += w
        for v, w2 in g[u]:
            if not in_tree[v]:
                heapq.heappush(pq, (w2, v))
    return total

def prim_dense(adj):
    n = len(adj)
    in_tree = [False] * n
    key = [float('inf')] * n
    key[0] = 0
    total = 0
    for _ in range(n):
        u = -1
        best = float('inf')
        for i in range(n):
            if not in_tree[i] and key[i] < best:
                best = key[i]
                u = i
        if u == -1:
            break
        in_tree[u] = True
        total += best
        for v in range(n):
            if not in_tree[v] and adj[u][v] < key[v]:
                key[v] = adj[u][v]
    return total

def kruskal(n, edges):
    parent = list(range(n))
    size = [1] * n
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    total = 0
    for u, v, w in sorted(edges, key=lambda e: e[2]):
        ru, rv = find(u), find(v)
        if ru != rv:
            if size[ru] < size[rv]:
                ru, rv = rv, ru
            parent[rv] = ru
            size[ru] += size[rv]
            total += w
    return total

