def tarjan_scc(g):
    n = len(g)
    idx = [-1] * n
    low = [0] * n
    onstack = [False] * n
    stack = []
    sccs = []
    counter = 0
    def dfs(u):
        nonlocal counter
        idx[u] = low[u] = counter
        counter += 1
        stack.append(u)
        onstack[u] = True
        for v in g[u]:
            if idx[v] == -1:
                dfs(v)
                low[u] = min(low[u], low[v])
            elif onstack[v]:
                low[u] = min(low[u], idx[v])
        if low[u] == idx[u]:
            comp = []
            while True:
                w = stack.pop()
                onstack[w] = False
                comp.append(w)
                if w == u:
                    break
            sccs.append(comp)
    for u in range(n):
        if idx[u] == -1:
            dfs(u)
    return sccs

def kosaraju(g):
    n = len(g)
    visited = [False] * n
    order = []
    def dfs1(u):
        visited[u] = True
        for v in g[u]:
            if not visited[v]:
                dfs1(v)
        order.append(u)
    for u in range(n):
        if not visited[u]:
            dfs1(u)
    rg = [[] for _ in range(n)]
    for u in range(n):
        for v in g[u]:
            rg[v].append(u)
    comp = [-1] * n
    def dfs2(u, c):
        comp[u] = c
        for v in rg[u]:
            if comp[v] == -1:
                dfs2(v, c)
    c = 0
    for u in reversed(order):
        if comp[u] == -1:
            dfs2(u, c)
            c += 1
    return comp, c

def find_bridges(g):
    n = len(g)
    disc = [-1] * n
    low = [0] * n
    bridges = []
    t = 0
    def dfs(u, parent):
        nonlocal t
        disc[u] = low[u] = t
        t += 1
        for v in g[u]:
            if v == parent:
                continue
            if disc[v] == -1:
                dfs(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    bridges.append((u, v))
            else:
                low[u] = min(low[u], disc[v])
    for u in range(n):
        if disc[u] == -1:
            dfs(u, -1)
    return bridges

def articulation_points(g):
    n = len(g)
    disc = [-1] * n
    low = [0] * n
    ap = [False] * n
    t = 0
    def dfs(u, parent):
        nonlocal t
        disc[u] = low[u] = t
        t += 1
        children = 0
        for v in g[u]:
            if v == parent:
                continue
            if disc[v] == -1:
                children += 1
                dfs(v, u)
                low[u] = min(low[u], low[v])
                if parent == -1 and children > 1:
                    ap[u] = True
                elif parent != -1 and low[v] >= disc[u]:
                    ap[u] = True
            else:
                low[u] = min(low[u], disc[v])
    for u in range(n):
        if disc[u] == -1:
            dfs(u, -1)
    return [i for i in range(n) if ap[i]]

