def traversal(kind, g, start):
    seen = {start}
    if kind == 'bfs':
        from collections import deque
        q = deque([start])
        while q:
            u = q.popleft()
            for v in g[u]:
                if v not in seen:
                    seen.add(v)
                    q.append(v)
    else:
        stack = [start]
        while stack:
            u = stack.pop()
            for v in g[u]:
                if v not in seen:
                    seen.add(v)
                    stack.append(v)
    return seen

