def dinic(n, edges, s, t):
    # edges: list of (u, v, cap) to build residual network
    graph = [[] for _ in range(n)]
    def add(u, v, cap):
        graph[u].append([v, cap, len(graph[v])])
        graph[v].append([u, 0, len(graph[u]) - 1])
    for u, v, c in edges:
        add(u, v, c)
    flow = 0
    while True:
        level = [-1] * n
        level[s] = 0
        q = [s]
        for u in q:
            for e in graph[u]:
                if e[1] and level[e[0]] == -1:
                    level[e[0]] = level[u] + 1
                    q.append(e[0])
        if level[t] == -1:
            break
        it = [0] * n
        def dfs(u, f):
            if u == t:
                return f
            for i in range(it[u], len(graph[u])):
                it[u] = i
                e = graph[u][i]
                if e[1] and level[e[0]] == level[u] + 1:
                    d = dfs(e[0], min(f, e[1]))
                    if d:
                        e[1] -= d
                        graph[e[0]][e[2]][1] += d
                        return d
            return 0
        while True:
            f = dfs(s, float('inf'))
            if not f:
                break
            flow += f
    return flow

def eulerian_path(g, start):
    stack = [start]
    path = []
    while stack:
        u = stack[-1]
        if g[u]:
            v = g[u].pop()
            stack.append(v)
        else:
            path.append(stack.pop())
    return path[::-1]

def reachable(n, edges, s, t):
    g = [[] for _ in range(n)]
    for u, v in edges:
        g[u].append(v)
        g[v].append(u)
    seen = {s}
    stack = [s]
    while stack:
        u = stack.pop()
        for v in g[u]:
            if v not in seen:
                seen.add(v)
                stack.append(v)
    return t in seen

def split_graph(n, adj, cap):
    N = 2 * n
    g = [[] for _ in range(N)]
    for u in range(n):
        g[2 * u].append((2 * u + 1, cap[u]))
    for u, v, w in adj:
        g[2 * u + 1].append((2 * v, w))
    return g
